"""Practice pack z1, VARC (original passages and verbal items written for AptiSetu, added 12 Nov 2026).
No text is taken from CAT papers, coaching material or any published source. Each item was written with one clearly
best option and re-read blind (answer hidden) before inclusion; para-jumble answers are checked to be permutations.
Calibration:
- Easy:   ~420-word passage in plain prose; questions on stated detail, simple inference and main idea; VA items
          with clear linking words (~1.5-2 min/question).
- Medium: denser ~450-word argument; inference, author's attitude, assumption, the role of an example; VA items
          with fewer explicit connectors and closer distractors (~2-2.5 min/question)."""

def P(*paras): return "".join(f"<p>{x}</p>" for x in paras)
PJ_HEAD = "<p>The four sentences below, when properly sequenced, form a coherent paragraph. Enter the sequence of the four numbers (e.g. 2143).</p>"
OS_HEAD = "<p>Five jumbled sentences related to a topic are given below. Four of them can be put together to form a coherent paragraph. Identify the odd one out and key in its number.</p>"
SUM_HEAD = "<p>The passage given below is followed by four summaries. Choose the option that best captures the essence of the passage.</p>"
COMP_HEAD = "<p>There is a sentence or phrase missing in the paragraph below. Read the paragraph and choose the option that best completes it.</p>"
def ol(xs): return "<ol class='pj'>" + "".join(f"<li>{x}</li>" for x in xs) + "</ol>"

SETS = []   # (level, set_id, title, passage_html, rc_questions, va_items)

